import json

with open('results_mini_pilot_v2/episodes.jsonl') as f:
    for line in f:
        r = json.loads(line)
        if r.get('condition') != 'ambiguous':
            continue
        cid = r['clause_id']
        traj = r.get('trajectory', [])
        print(f'=== {cid} (ambiguous) ===')
        for step in traj:
            role = step.get('role', '?')
            content = step.get('content', '')
            if isinstance(content, str):
                print(f'  [{role}] {content[:300]}')
            elif isinstance(content, list):
                for part in content:
                    if isinstance(part, dict):
                        if part.get('type') == 'text':
                            print(f'  [{role}] {part[\"text\"][:300]}')
                        elif 'function_call' in part or part.get('type') == 'function_call':
                            print(f'  [{role}] TOOL_CALL: {str(part)[:200]}')
                        else:
                            print(f'  [{role}] {str(part)[:200]}')
        print()
